namespace HakutaiKagami.Core.Contracts;
public enum TradeAction { Quote,Accept,Collect,OfferSale,Deliver,Settle,Cancel,SupplyHouse,OfferOwnRice }
public enum TradePhase { Offered,Accepted,Carrying,SaleQuoted,Delivered,Settled,Cancelled,Expired,ReturnRequired,Supplied }
public sealed record TradeInput(EntityId Id,TradeAction Action,EntityId Site,EntityId? Contract=null,EntityId? Destination=null,long Amount=0) { [System.Text.Json.Serialization.JsonIgnore(Condition=System.Text.Json.Serialization.JsonIgnoreCondition.WhenWritingNull)] public string? Commodity {get;init;} }
public sealed record TradeEntry(TradeInput Input,EntityId Actor,long At,long Revision,long Price);
public sealed record TradeMarket(EntityId Site,long Rice,long Cash) { [System.Text.Json.Serialization.JsonIgnore(Condition=System.Text.Json.Serialization.JsonIgnoreCondition.WhenWritingNull)] public MaterialStock[]? Goods {get;init;} }
public sealed record TradeDeal(EntityId Id,EntityId Source,EntityId Destination,long Amount,long PurchasePrice,long QuotedAt,long AcceptBy,long CollectBy,TradePhase Phase,EntityId? SaleSite=null,long SalePrice=0,long SaleBy=0) { [System.Text.Json.Serialization.JsonIgnore(Condition=System.Text.Json.Serialization.JsonIgnoreCondition.WhenWritingNull)] public string? Commodity {get;init;} }
public sealed record RegionalTradeState(int Schema,string Policy,TradeEntry[] Entries,TradeMarket[] Markets,TradeDeal[] Deals);
public sealed record TradeLocalView(EntityId Site,long ObservedAt,long BuyPrice,long SellPrice,long RiceAvailable,long CashAvailable,long PrivateAvailable,TradeDeal[] Deals) { [System.Text.Json.Serialization.JsonIgnore(Condition=System.Text.Json.Serialization.JsonIgnoreCondition.WhenWritingNull)] public CommodityQuote[]? Goods {get;init;} }
