    internal static RegionalTradeState SnapshotAt(ContractWorld w,long at,long rev)=>Replay(w,w.Trade!.Entries.Where(e=>Before(e,at,rev)).ToArray(),at,rev-1);
    internal static long StockFree(RegionalTradeState s,EntityId site,string? kind)=>MaterialMarkets.Stock(s.Markets.Single(m=>m.Site==site),kind)-RiceReserved(s.Deals,site,kind);
    internal static long CashFree(RegionalTradeState s,EntityId site)=>s.Markets.Single(m=>m.Site==site).Cash-CashReserved(s.Deals,site);
    internal static void Initialize(ContractWorld w){if(Enabled(w)){w.TravelDecisions??=[];w.TrafficStops??=[];w.Trade=Replay(w,[],0,w.CommitSequence);}}
    internal static void Tick(ContractWorld w){if(Enabled(w))w.Trade=Replay(w,w.Trade!.Entries,w.ElapsedSeconds,w.CommitSequence);}
    internal static void Apply(ContractWorld w,TradeInput i){var price=i.Action is TradeAction.Quote or TradeAction.OfferSale?QuotePrice(w.Trade!.Markets.Single(m=>m.Site==i.Site),i.Action==TradeAction.Quote,i.Action==TradeAction.Quote?i.Commodity:w.Trade!.Deals.Single(d=>d.Id==i.Contract).Commodity):0;var e=new TradeEntry(i,w.PlayerControl,w.ElapsedSeconds,w.CommitSequence,price);w.Trade=w.Trade! with{Entries=[..w.Trade.Entries,e]};Tick(w);NewGameWork.Sync(w);}
