public sealed partial class WorldSession
{
    public TradeLocalView? RegionalTradeView(){lock(gate)return RegionalTrade.View(state);}
    public CommandResult TradeRice(TradeInput input,EntityId actor,long revision){lock(gate){if(actor!=state.PlayerControl||!RegionalTrade.Enabled(state))return new(ResultCode.NotAvailable,input.Id,state.CommitSequence,"本人の現地取引ではありません");var old=state.Trade!.Entries.SingleOrDefault(e=>e.Input.Id==input.Id);if(old!=null)return new(old.Input==input?ResultCode.AlreadyAccepted:ResultCode.IdPayloadConflict,input.Id,state.CommitSequence,"処理済みの売買操作です");if(FactionStances.OtherIdUsed(state,input.Id)||FactionStances.OwnIdUsed(state,input.Id))return new(ResultCode.IdPayloadConflict,input.Id,state.CommitSequence,"別操作で使用済みの原本IDです");if(revision!=state.CommitSequence)return new(ResultCode.StateChanged,input.Id,state.CommitSequence,"現地の条件を確認し直してください");try{Change(w=>RegionalTrade.Apply(w,input));return new(ResultCode.Accepted,input.Id,state.CommitSequence,"米と銭の売買原本へ記録しました");}catch(Exception e)when(e is InvalidDataException or InvalidOperationException or ArgumentException or OverflowException){return new(ResultCode.NotAvailable,input.Id,state.CommitSequence,e.Message);}}}
